  "pdp.bullet.cluster": "सूचीबद्ध करबा सँ पहिने शिल्प क्लस्टर द्वारा परम्परागत तकनीक केर जाँच कएल गेल।",
  "pdp.bullet.material": "सामग्री: {material}। रंग आ बुनाई मे हल्का अंतर हाथ सँ बनल केर प्रमाण अछि, कमी नहि।",
  "pdp.bullet.mto": "ऑर्डर पर बनैत अछि: कार्य अहाँक ऑर्डर केर बाद शुरू होइत अछि, तेँ अनुरोध पर परिवर्तन संभव।",
  "pdp.bullet.ready": "तैयार स्टॉक: कारीगर 2 कार्य दिवस मे पैक कए पठाओत।",
  "pdp.bullet.direct": "राशि सीधे {artisan} केर बैंक खाता मे जाइत अछि — कोनो बिचौलिया नहि।",
  "pdp.bullet.sealed": "सत्यापित तकनीक दर्ज करैत, छेड़छाड़-रोधी प्रामाणिकता मुद्रा संगे पठाओल जाइत अछि।",
